import sys
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
import numpy as np
r=Robot(timeout=30); o=r.get_obs(cameras=('head_camera',),include_depth=True,video='none')
img=o.last['head_camera']; d=np.squeeze(o.depth['head_camera']).astype(float)/1000; K=np.array(o.meta['cameras']['head_camera']['intrinsic_cv']); E=np.vstack([np.array(o.meta['cameras']['head_camera']['extrinsic_cv']),[0,0,0,1]]); Ei=np.linalg.inv(E)
pts=[]
for v in range(65,145):
 for u in range(215,320):
  if max(img[v,u])<90:
   z=d[v,u]; pc=np.array([(u-160)*z/K[0,0],(v-120)*z/K[1,1],z,1]); p=(Ei@pc)[:3]
   if .78<p[2]<.86 and -.12<p[1]<.12 and .05<p[0]<.32: pts.append(p)
P=np.array(pts); c=P.mean(0); val,V=np.linalg.eigh(np.cov(P.T));
print('n',len(P),'center',c,'eval',val)
print('axes columns',V)
for j in range(3):
 proj=(P-c)@V[:,j]; print(j,proj.min(),proj.max(),np.quantile(proj,[.1,.5,.9]))
