m=json.load(open('/app/output/control/before_approach/meta.json'));cam=m['cameras']['head_camera'];K=np.array(cam['intrinsic_cv']);E=np.vstack([np.array(cam['extrinsic_cv']),[0,0,0,1]]);Ei=np.linalg.inv(E)
for threshold in (100,150,190,220,240):
 P=[]
 for v in range(35,115):
  for u in range(165,250):
   if max(img[v,u])<threshold:
    z=d[v,u]
    if not(.4<z<1.1):continue
    pc=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]);p=(Ei@pc)[:3]
