 P=np.array(P)
 print('\nthr',threshold,'n',len(P))
 if len(P):
  c=np.median(P,axis=0);val,V=np.linalg.eigh(np.cov((P-c).T));print('med',c.round(3),'eval',val.round(5));print('axes',V.round(3));
